//! Prover-local public byte carrier and selected terminal wrapper.
use alloc::vec::Vec;
use aspis_core::{
    field::{M31, QM31},
    state_only_prefix::r0::{Challenges, Error},
};
use aspis_statement::pool_v1::pair_forest_semantic_terminal::r0::Public;
#[derive(Clone, Copy)]
pub struct OwnedPublic {
    pub withdrawal: bool,
    pub anchor: [u32; 8],
    pub nullifier: [u32; 8],
    pub asset_id: u32,
    pub recipient: [u32; 8],
    pub change: [u32; 8],
    pub withdrawal_amount: u32,
    pub next_pair_index: u64,
    pub frontier: [[u32; 8]; 20],
    pub next_root: [u32; 8],
    pub next_frontier: [[u32; 8]; 20],
}
#[inline(never)]
fn canonical(v: u32) -> Option<u32> {
    if v < 2147483647 {
        Some(v)
    } else {
        None
    }
}
#[inline(never)]
fn field_byte(v: u32, j: usize) -> Result<u8, Error> {
    let v = match canonical(v) {
        Some(v) => v,
        None => return Err(Error::Public),
    };
    Ok((v >> (8u32 * (j as u32))) as u8)
}
#[inline(never)]
fn byte_at(p: OwnedPublic, i: usize) -> Result<u8, Error> {
    if i == 0 {
        return Ok(if p.withdrawal { 1 } else { 0 });
    }
    if i < 33 {
        return field_byte(p.anchor[(i - 1) / 4], (i - 1) % 4);
    }
    if i < 65 {
        return field_byte(p.nullifier[(i - 33) / 4], (i - 33) % 4);
    }
    if i < 69 {
        return field_byte(p.asset_id, i - 65);
    }
    if i == 69 {
        return Ok(if p.withdrawal { 0 } else { 1 });
    }
    let change = if p.withdrawal { 70 } else { 102 };
    if i < change {
        return field_byte(p.recipient[(i - 70) / 4], (i - 70) % 4);
    }
    if i < change + 32 {
        return field_byte(p.change[(i - change) / 4], (i - change) % 4);
    }
    if i == change + 32 {
        return Ok(if p.withdrawal { 1 } else { 0 });
    }
    let index = if p.withdrawal { 107 } else { 135 };
    if i < index {
        return field_byte(p.withdrawal_amount, i - (change + 33));
    }
    if i < index + 8 {
        return Ok((p.next_pair_index >> (8u32 * ((i - index) as u32))) as u8);
    }
    let front = index + 8;
    if i < front + 640 {
        let j = i - front;
        return field_byte(p.frontier[j / 32][(j % 32) / 4], j % 4);
    }
    if i < front + 672 {
        let j = i - front - 640;
        return field_byte(p.next_root[j / 4], j % 4);
    }
    let j = i - front - 672;
    field_byte(p.next_frontier[j / 32][(j % 32) / 4], j % 4)
}
pub fn encode_owned(p: OwnedPublic) -> Result<([u8; 1455], usize), Error> {
    let n = if p.withdrawal { 1427 } else { 1455 };
    let mut out = [0u8; 1455];
    let mut i = 0usize;
    while i < n {
        out[i] = byte_at(p, i)?;
        i += 1;
    }
    Ok((out, n))
}

pub fn project(public: Public<'_>) -> OwnedPublic {
    let (withdrawal, anchor, nullifier, asset_id, recipient, change, withdrawal_amount, transition) =
        match public {
            Public::Transfer(p, t) => (
                false,
                p.anchor_root,
                p.nullifier,
                p.asset_id,
                p.recipient_commitment,
                p.change_commitment,
                0,
                *t,
            ),
            Public::Withdrawal(p, t) => (
                true,
                p.anchor_root,
                p.nullifier,
                p.asset_id,
                [M31::ZERO; 8],
                p.change_commitment,
                p.amount,
                *t,
            ),
        };
    let mut out = OwnedPublic {
        withdrawal,
        anchor: [0; 8],
        nullifier: [0; 8],
        asset_id: asset_id.0,
        recipient: [0; 8],
        change: [0; 8],
        withdrawal_amount,
        next_pair_index: transition.live_snapshot.next_pair_index,
        frontier: [[0; 8]; 20],
        next_root: [0; 8],
        next_frontier: [[0; 8]; 20],
    };
    out.anchor[0] = anchor[0].0;
    out.nullifier[0] = nullifier[0].0;
    out.recipient[0] = recipient[0].0;
    out.change[0] = change[0].0;
    out.next_root[0] = transition.candidate_afterstate.next_root[0].0;
    out.anchor[1] = anchor[1].0;
    out.nullifier[1] = nullifier[1].0;
    out.recipient[1] = recipient[1].0;
    out.change[1] = change[1].0;
    out.next_root[1] = transition.candidate_afterstate.next_root[1].0;
    out.anchor[2] = anchor[2].0;
    out.nullifier[2] = nullifier[2].0;
    out.recipient[2] = recipient[2].0;
    out.change[2] = change[2].0;
    out.next_root[2] = transition.candidate_afterstate.next_root[2].0;
    out.anchor[3] = anchor[3].0;
    out.nullifier[3] = nullifier[3].0;
    out.recipient[3] = recipient[3].0;
    out.change[3] = change[3].0;
    out.next_root[3] = transition.candidate_afterstate.next_root[3].0;
    out.anchor[4] = anchor[4].0;
    out.nullifier[4] = nullifier[4].0;
    out.recipient[4] = recipient[4].0;
    out.change[4] = change[4].0;
    out.next_root[4] = transition.candidate_afterstate.next_root[4].0;
    out.anchor[5] = anchor[5].0;
    out.nullifier[5] = nullifier[5].0;
    out.recipient[5] = recipient[5].0;
    out.change[5] = change[5].0;
    out.next_root[5] = transition.candidate_afterstate.next_root[5].0;
    out.anchor[6] = anchor[6].0;
    out.nullifier[6] = nullifier[6].0;
    out.recipient[6] = recipient[6].0;
    out.change[6] = change[6].0;
    out.next_root[6] = transition.candidate_afterstate.next_root[6].0;
    out.anchor[7] = anchor[7].0;
    out.nullifier[7] = nullifier[7].0;
    out.recipient[7] = recipient[7].0;
    out.change[7] = change[7].0;
    out.next_root[7] = transition.candidate_afterstate.next_root[7].0;
    out = project_frontier_level(out, transition, 0);
    out = project_frontier_level(out, transition, 1);
    out = project_frontier_level(out, transition, 2);
    out = project_frontier_level(out, transition, 3);
    out = project_frontier_level(out, transition, 4);
    out = project_frontier_level(out, transition, 5);
    out = project_frontier_level(out, transition, 6);
    out = project_frontier_level(out, transition, 7);
    out = project_frontier_level(out, transition, 8);
    out = project_frontier_level(out, transition, 9);
    out = project_frontier_level(out, transition, 10);
    out = project_frontier_level(out, transition, 11);
    out = project_frontier_level(out, transition, 12);
    out = project_frontier_level(out, transition, 13);
    out = project_frontier_level(out, transition, 14);
    out = project_frontier_level(out, transition, 15);
    out = project_frontier_level(out, transition, 16);
    out = project_frontier_level(out, transition, 17);
    out = project_frontier_level(out, transition, 18);
    out = project_frontier_level(out, transition, 19);
    out
}
pub fn public_bytes(public: Public<'_>) -> Result<([u8; 1455], usize), Error> {
    encode_owned(project(public))
}
pub fn materialize_public_bytes(public: Public<'_>) -> Result<Vec<u8>, Error> {
    let (bytes, len) = public_bytes(public)?;
    Ok(bytes[..len].to_vec())
}
pub fn terminal_qm31(
    public: Public<'_>,
    claims: &[[QM31; 29]; 3],
    alpha: &[QM31; 10],
    c: &Challenges,
) -> Result<QM31, Error> {
    let p = match public {
        Public::Transfer(p, t) => crate::host_terminal::r0::Public::Transfer(p, t),
        Public::Withdrawal(p, t) => crate::host_terminal::r0::Public::Withdrawal(p, t),
    };
    p.terminal_qm31(claims, alpha, c)
}

#[inline(never)]
fn frontier_word(frontier: &[[M31; 8]; 20], level: usize, i: usize) -> u32 { frontier[level][i].0 }

#[inline(always)]
fn project_frontier_level(mut out: OwnedPublic, transition: aspis_statement::pool_v1::pair_tree_profile::PoolV1PairLatePublicStatementV1, level: usize) -> OwnedPublic {
    out.frontier[level][0] = transition.live_snapshot.frontier[level][0].0;
    out.next_frontier[level][0] = transition.candidate_afterstate.next_frontier[level][0].0;
    out.frontier[level][1] = transition.live_snapshot.frontier[level][1].0;
    out.next_frontier[level][1] = transition.candidate_afterstate.next_frontier[level][1].0;
    out.frontier[level][2] = transition.live_snapshot.frontier[level][2].0;
    out.next_frontier[level][2] = transition.candidate_afterstate.next_frontier[level][2].0;
    out.frontier[level][3] = transition.live_snapshot.frontier[level][3].0;
    out.next_frontier[level][3] = transition.candidate_afterstate.next_frontier[level][3].0;
    out.frontier[level][4] = transition.live_snapshot.frontier[level][4].0;
    out.next_frontier[level][4] = transition.candidate_afterstate.next_frontier[level][4].0;
    out.frontier[level][5] = transition.live_snapshot.frontier[level][5].0;
    out.next_frontier[level][5] = transition.candidate_afterstate.next_frontier[level][5].0;
    out.frontier[level][6] = transition.live_snapshot.frontier[level][6].0;
    out.next_frontier[level][6] = transition.candidate_afterstate.next_frontier[level][6].0;
    out.frontier[level][7] = transition.live_snapshot.frontier[level][7].0;
    out.next_frontier[level][7] = transition.candidate_afterstate.next_frontier[level][7].0;
    out
}

//! Allocation-bounded selected terminal for the eight-lane Pool V1 pair
//! forest. The relation keeps the frozen Tag-73 three-opening geometry and
//! packs Poseidon, 94 semantic source lanes and the 136-link Copy argument
//! into the same 29 theta lanes as the one-tree payment terminal.


// Closure-free array construction, evaluated in increasing source index order.
macro_rules! qm31_array {
    ($n:expr, $index:ident, $body:expr) => {{
        let mut output = [QM31::ZERO; $n];
        let mut $index = 0usize;
        while $index < $n {
            output[$index] = $body;
            $index += 1;
        }
        output
    }};
}

use crate::host_terminal_field::{qm31_pack_base4, PreparedQm31Multiplier};
use aspis_core::{
    field::{CM31, M31, QM31},
    state_only_hiding::STATE_ONLY_HIDING_MASK_ONLY_C1_COLUMNS,
};

use aspis_statement::{
    poseidon2::{Digest, DIGEST_ELEMS, MERKLE_NODE_COMPRESSION_V3_TWEAK, POSEIDON2_WIDTH, RATE},
    state_only_poseidon::{
        evaluate_state_only_poseidon_oracle_projected, StateOnlyPoseidonOpenings,
        StateOnlyPoseidonSelectors,
    },
};

use aspis_statement::pool_v1::{
    pair_tree_profile::{PoolV1PairLatePublicStatementV1, POOL_V1_PAIR_CAPACITY},
    payment_relation::{PoolV1PrivateTransferPublicV1, PoolV1WithdrawalPublicV1},
};

use aspis_prover::host_arithmetic::state_only_selected_mask_value;
use crate::host_copy_terminal::{evaluate_with_selectors,PoolV1PairForestCompiledVariantV1,Selectors};

const DOMAIN_OWNER_KEY:M31=M31(0x4153_0001);
const DOMAIN_NULLIFIER:M31=M31(0x4153_0002);
const DOMAIN_NOTE:M31=M31(0x4153_0003);

pub const POOL_V1_PAIR_FOREST_TERMINAL_ROWS_V1: usize = 1024;
pub const POOL_V1_PAIR_FOREST_TERMINAL_C1_COLUMNS_V1: usize = 16;
pub const POOL_V1_PAIR_FOREST_TERMINAL_POINTS_V1: usize = 3;
pub const POOL_V1_PAIR_FOREST_SELECTED_TERMINAL_COLUMNS_V1: usize =
    POOL_V1_PAIR_FOREST_TERMINAL_C1_COLUMNS_V1 + STATE_ONLY_HIDING_MASK_ONLY_C1_COLUMNS + 2;
pub const POOL_V1_PAIR_FOREST_SELECTED_TERMINAL_CLAIMS_V1: usize =
    POOL_V1_PAIR_FOREST_TERMINAL_POINTS_V1 * POOL_V1_PAIR_FOREST_SELECTED_TERMINAL_COLUMNS_V1;
pub const POOL_V1_PAIR_FOREST_SOURCE_SEMANTIC_LANES_V1: usize = 94;
pub const POOL_V1_PAIR_FOREST_PACKED_SEMANTIC_LANES_V1: usize = 24;
pub const POOL_V1_PAIR_FOREST_POSEIDON_LANES_V1: usize = 4;
pub const POOL_V1_PAIR_FOREST_COPY_LANES_V1: usize = 1;
pub const POOL_V1_PAIR_FOREST_THETA_LANES_V1: usize = POOL_V1_PAIR_FOREST_POSEIDON_LANES_V1
    + POOL_V1_PAIR_FOREST_PACKED_SEMANTIC_LANES_V1
    + POOL_V1_PAIR_FOREST_COPY_LANES_V1;
pub const POOL_V1_PAIR_FOREST_THETA_COLLISION_DEGREE_V1: usize =
    POOL_V1_PAIR_FOREST_THETA_LANES_V1 - 1;
pub const POOL_V1_PAIR_FOREST_SEMANTIC_ORACLE_INDIVIDUAL_DEGREE_V1: usize = 26;
pub const POOL_V1_PAIR_FOREST_SEMANTIC_ZEROCHECK_INDIVIDUAL_DEGREE_V1: usize = 27;
pub const POOL_V1_PAIR_FOREST_MASKED_TERMINAL_DEGREE_V1: usize = 27;
pub const POOL_V1_PAIR_FOREST_TERMINAL_FIXED_HEAP_ALLOCATIONS_V1: usize =
    if cfg!(feature = "optimized-terminal") {
        2
    } else {
        1
    };
pub const POOL_V1_PAIR_FOREST_TERMINAL_SELECTOR_HEAP_BYTES_V1: usize =
    core::mem::size_of::<Selectors>();

const SELECTED_H1_COLUMN: usize =
    POOL_V1_PAIR_FOREST_TERMINAL_C1_COLUMNS_V1 + STATE_ONLY_HIDING_MASK_ONLY_C1_COLUMNS;
const SELECTED_G_COLUMN: usize = SELECTED_H1_COLUMN + 1;
const VALUE_AUXILIARY_BLOCK: usize = 63;
const INPUT_OCCUPANCY_ROW: usize = 63 * 16 + 9;
const OUTPUT_OCCUPANCY_ROW: usize = 63 * 16 + 10;

const _: () = assert!(DIGEST_ELEMS == 8);
const _: () = assert!(POSEIDON2_WIDTH == 16);
const _: () = assert!(POOL_V1_PAIR_FOREST_SELECTED_TERMINAL_COLUMNS_V1 == 28);
const _: () = assert!(POOL_V1_PAIR_FOREST_SELECTED_TERMINAL_CLAIMS_V1 == 84);
const _: () = assert!(POOL_V1_PAIR_FOREST_THETA_LANES_V1 == 29);
const _: () = assert!(POOL_V1_PAIR_FOREST_THETA_COLLISION_DEGREE_V1 == 28);

mod constants {
    include!("host_terminal_constants.rs");
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PoolV1PairForestSemanticTerminalErrorV1 {
    InvalidPublicAmount,
    InvalidAppendTransition,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CompiledVariant {
    PrivateTransfer,
    Withdrawal,
}

#[derive(Clone, Copy)]
struct SemanticPublic {
    variant: CompiledVariant,
    pool: [u8; 32],
    deployment_domain: [u8; 32],
    anchor: Digest,
    nullifier: Digest,
    asset_id: M31,
    recipient: Option<Digest>,
    change: Digest,
    withdrawal_amount: Option<u32>,
    transition: PoolV1PairLatePublicStatementV1,
}

#[inline(always)]
fn lift_m31(value: M31) -> QM31 {
    QM31::from_cm31(CM31::from_m31(value))
}

/// Count only the trailing one bits used by the twenty-level append tree.
/// The bounded form is equivalent to capping u64::trailing_ones at twenty.
fn bounded_append_carry(mut index: u64) -> usize {
    let mut carry = 0usize;
    while carry < 20 {
        if index & 1 == 0 {
            return carry;
        }
        index >>= 1u32;
        carry += 1;
    }
    carry
}

#[inline(always)]
fn add_preweighted<const N: usize>(
    packed: &mut [QM31; POOL_V1_PAIR_FOREST_PACKED_SEMANTIC_LANES_V1],
    start: usize,
    values: &[QM31; N],
) {
    let first = start / 4;
    let last = (start + N - 1) / 4;
    for group in first..=last {
        let lanes: [QM31; 4] = qm31_array!(4, slot, {
            let source = 4 * group + slot;
            if source >= start && source < start + N {
                values[source - start]
            } else {
                QM31::ZERO
            }
        });
        packed[group] = packed[group].add(qm31_pack_base4(&lanes));
    }
}

/// Exact linear factoring for a contiguous source-lane interval with one
/// common selector:
///
/// `pack(s*r0, ..., s*r3) = s*pack(r0, ..., r3)`.
///
/// The global source offset may be unaligned, so the first and last groups
/// retain the same zero padding as `add_preweighted`.
#[inline(always)]
#[cfg(any(test, feature = "optimized-terminal"))]
fn add_preweighted_shared_selector<const N: usize>(
    packed: &mut [QM31; POOL_V1_PAIR_FOREST_PACKED_SEMANTIC_LANES_V1],
    start: usize,
    values: &[QM31; N],
    selector: QM31,
) {
    let first = start / 4;
    let last = (start + N - 1) / 4;
    for group in first..=last {
        let lanes: [QM31; 4] = qm31_array!(4, slot, {
            let source = 4 * group + slot;
            if source >= start && source < start + N {
                values[source - start]
            } else {
                QM31::ZERO
            }
        });
        packed[group] = packed[group].add(selector.mul(qm31_pack_base4(&lanes)));
    }
}

#[inline(always)]
fn sum_high(selectors: &Selectors, ranges: &[core::ops::Range<usize>]) -> QM31 {
    let mut sum = QM31::ZERO;
    for range in ranges {
        for block in range.clone() {
            sum = sum.add(selectors.high[block]);
        }
    }
    sum
}

#[inline(always)]
fn reconstruct_10(view: &[QM31; 16]) -> QM31 {
    let mut acc = view[9];
    let mut index = 9usize;
    while index > 0 {
        index -= 1;
        acc = acc.add(acc).add(view[index]);
    }
    acc
}

#[inline(always)]
fn empty_root(level: usize) -> Digest {
    let words = constants::POOL_V1_PAIR_EMPTY_ROOTS_V1[level];
    [M31(words[0]), M31(words[1]), M31(words[2]), M31(words[3]),
     M31(words[4]), M31(words[5]), M31(words[6]), M31(words[7])]
}

fn validate_transition(
    public: SemanticPublic,
) -> Result<(), PoolV1PairForestSemanticTerminalErrorV1> {
    let source = public.transition.live_snapshot;
    let after = public.transition.candidate_afterstate;
    if source.pool != public.pool
        || source.deployment_domain != public.deployment_domain
        || source.sequence != source.next_pair_index
        || source.next_pair_index >= POOL_V1_PAIR_CAPACITY
        || source.next_pair_index.checked_add(1) != Some(after.next_pair_index)
    {
        return Err(PoolV1PairForestSemanticTerminalErrorV1::InvalidAppendTransition);
    }
    let index = source.next_pair_index;
    let carry = bounded_append_carry(index);
    for level in 0..20 {
        if level == carry && carry < 20 {
            continue;
        }
        let expected = if level < carry || ((index >> level) & 1) == 0 {
            empty_root(level)
        } else {
            source.frontier[level]
        };
        if after.next_frontier[level] != expected {
            return Err(PoolV1PairForestSemanticTerminalErrorV1::InvalidAppendTransition);
        }
    }
    Ok(())
}

fn poseidon_selectors(selectors: &Selectors) -> StateOnlyPoseidonSelectors {
    StateOnlyPoseidonSelectors {
        block: sum_high(selectors, &[0..57]),
        local: selectors.low,
    }
}

#[inline(never)]
fn initial_variant_selectors(
    variant: CompiledVariant,
    high27: QM31,
    high28: QM31,
    high29: QM31,
) -> (QM31, QM31, QM31, QM31) {
    match variant {
        CompiledVariant::PrivateTransfer => (
            high27,
            QM31::ZERO,
            high27.add(high28),
            high29,
        ),
        CompiledVariant::Withdrawal => (
            QM31::ZERO,
            high27.add(high28).add(high29),
            QM31::ZERO,
            QM31::ZERO,
        ),
    }
}

fn semantic_initial_and_absorption(
    public: SemanticPublic,
    openings: &StateOnlyPoseidonOpenings,
    selectors: &Selectors,
) -> ([QM31; 16], [QM31; 16]) {
    let nodes = sum_high(selectors, &[4..25, 33..57]);
    let first_common = selectors.high[0]
        .add(selectors.high[1])
        .add(selectors.high[25])
        .add(selectors.high[30]);
    let (transfer_first, fixed, private_chunk_eight, private_chunk_two) =
        initial_variant_selectors(
            public.variant,
            selectors.high[27],
            selectors.high[28],
            selectors.high[29],
        );
    let full_initial_selector = selectors.low[0].mul(first_common.add(transfer_first).add(fixed));
    let rate_initial_selector = selectors.low[0].mul(nodes);
    let full = PreparedQm31Multiplier::new(full_initial_selector);
    let full_or_rate =
        PreparedQm31Multiplier::new(full_initial_selector.add(rate_initial_selector));
    let mut initial = qm31_array!(16, lane, {
        if lane < RATE {
            full_or_rate.mul(openings.z[lane])
        } else {
            full.mul(openings.z[lane])
        }
    });
    let note_first = selectors.high[1]
        .add(selectors.high[30])
        .add(transfer_first);
    let domain = selectors.high[0]
        .mul_m31(DOMAIN_OWNER_KEY)
        .add(note_first.mul_m31(DOMAIN_NOTE))
        .add(selectors.high[25].mul_m31(DOMAIN_NULLIFIER));
    let length = selectors.high[0]
        .mul_m31(M31(8))
        .add(note_first.mul_m31(M31(18)))
        .add(selectors.high[25].mul_m31(M31(16)));
    initial[RATE] = initial[RATE].sub(selectors.low[0].mul(domain));
    initial[RATE + 1] = initial[RATE + 1].sub(selectors.low[0].mul(length));

    let mut chunk_eight = selectors.high[0]
        .add(selectors.high[1])
        .add(selectors.high[2])
        .add(selectors.high[25])
        .add(selectors.high[26])
        .add(selectors.high[30])
        .add(selectors.high[31]);
    let mut chunk_two = selectors.high[3].add(selectors.high[32]);
    chunk_eight = chunk_eight.add(private_chunk_eight);
    chunk_two = chunk_two.add(private_chunk_two);
    #[cfg(not(feature = "optimized-terminal"))]
    let absorption = absorption_lanes_literal(
        selectors.low[12],
        fixed,
        chunk_two,
        chunk_eight,
        nodes,
        &openings.z,
    );
    #[cfg(feature = "optimized-terminal")]
    let absorption = absorption_lanes_factored(
        selectors.low[12],
        fixed,
        chunk_two,
        chunk_eight,
        nodes,
        &openings.z,
    );
    (initial, absorption)
}

#[cfg(any(test, not(feature = "optimized-terminal")))]
fn absorption_lanes_literal(
    low: QM31,
    fixed: QM31,
    chunk_two: QM31,
    chunk_eight: QM31,
    nodes: QM31,
    openings: &[QM31; 16],
) -> [QM31; 16] {
    qm31_array!(16, lane, {
        let blocks = if lane < 2 {
            fixed
        } else if lane < RATE {
            fixed.add(chunk_two)
        } else {
            fixed.add(chunk_two).add(chunk_eight).add(nodes)
        };
        low.mul(blocks).mul(openings[lane])
    })
}

#[cfg(any(test, feature = "optimized-terminal"))]
fn absorption_lanes_factored(
    low: QM31,
    fixed: QM31,
    chunk_two: QM31,
    chunk_eight: QM31,
    nodes: QM31,
    openings: &[QM31; 16],
) -> [QM31; 16] {
    let scales = [
        PreparedQm31Multiplier::new(low.mul(fixed)),
        PreparedQm31Multiplier::new(low.mul(fixed.add(chunk_two))),
        PreparedQm31Multiplier::new(low.mul(fixed.add(chunk_two).add(chunk_eight).add(nodes))),
    ];
    qm31_array!(16, lane, {
        let scale = if lane < 2 {
            scales[0]
        } else if lane < RATE {
            scales[1]
        } else {
            scales[2]
        };
        scale.mul(openings[lane])
    })
}

#[inline(always)]
#[cfg(any(test, not(feature = "optimized-terminal")))]
fn add_digest_binding(
    output: &mut [QM31; DIGEST_ELEMS],
    selector: QM31,
    opened: &[QM31; POSEIDON2_WIDTH],
    start: usize,
    expected: &Digest,
    right_tweak: bool,
) {
    for lane in 0..DIGEST_ELEMS {
        let mut target = expected[lane];
        if right_tweak && lane + 1 == DIGEST_ELEMS {
            target = target.add(MERKLE_NODE_COMPRESSION_V3_TWEAK);
        }
        output[lane] = output[lane].add(selector.mul(opened[start + lane].sub(lift_m31(target))));
    }
}

