pub enum PoolV1PairForestSemanticTerminalErrorV1 {
    InvalidPublicAmount,
    InvalidAppendTransition,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CompiledVariant {
    PrivateTransfer,
    Withdrawal,
}

#[derive(Clone, Copy)]
struct SemanticPublic {
    variant: CompiledVariant,
    pool: [u8; 32],
    deployment_domain: [u8; 32],
