            opened[RATE + 5].sub(lift_m31(expected[5])),
            opened[RATE + 6].sub(lift_m31(expected[6])),
            opened[RATE + 7]
                .sub(lift_m31(expected[7].add(MERKLE_NODE_COMPRESSION_V3_TWEAK))),
        ];
        (
            [
                prepared_high.mul(qm31_pack_base4(&residual0)),
