    frontier: Digest,
) -> [QM31; DIGEST_ELEMS / 4] {
    if carry < 20 {
        let prepared_high = PreparedQm31Multiplier::new(high);
        let residual0 = [
            opened[0].sub(lift_m31(frontier[0])),
            opened[1].sub(lift_m31(frontier[1])),
            opened[2].sub(lift_m31(frontier[2])),
