        local0[0] = local0[0].add(level0[0]);
        local0[1] = local0[1].add(level0[1]);
        local12[0] = local12[0].add(level12[0]);
        local12[1] = local12[1].add(level12[1]);
        level += 1;
    }
    (local0, local12)
}

