        output[COPY_GROUP_LOCAL_COORDINATE_GROUPS[coordinate] as usize]
            [COPY_GROUP_LOCAL_COORDINATE_LOCALS[coordinate] as usize] = coordinate as u8;
        coordinate += 1;
