            opened[7].sub(lift_m31(frontier[7])),
        ];
        (
            [QM31::ZERO; DIGEST_ELEMS / 4],
            [
                prepared_high.mul(qm31_pack_base4(&residual0)),
                prepared_high.mul(qm31_pack_base4(&residual1)),
            ],
        )
    }
}

#[cfg(any(
    test,
