#[inline(always)]
fn append_levels_packed_selector_tensor(
    next_pair_index: u64,
    frontier: [Digest; 20],
    opened: [QM31; POSEIDON2_WIDTH],
    selector_high: [QM31; 64],
) -> (
    [QM31; DIGEST_ELEMS / 4],
    [QM31; DIGEST_ELEMS / 4],
) {
    let mut local0 = [QM31::ZERO; DIGEST_ELEMS / 4];
    let mut local12 = [QM31::ZERO; DIGEST_ELEMS / 4];
    let mut level = 0usize;
